/*
 * Dashboard front end: loads data/catalog.json (generated by scripts/catalog.py); no data is embedded.
 * Bilingual (English / 中文): UI text lives in i18n.js; project summaries and
 * category names come in both languages from the data file.
 * Local preview needs a static server (browsers block file:// pages from reading local JSON):
 *   python3 -m http.server -d site 8000
 */
(function(){
  var requestedParams = new URLSearchParams(window.location.search);
  var requestedTab = requestedParams.get('tab');
  var initialQuery = requestedParams.get('q') || '';
  var initialScope = requestedParams.get('scope') === 'name' ? 'name' : 'all';
  var CURRENT_TAB = ['ai', 'fullstack'].indexOf(requestedTab) >= 0 ? requestedTab : 'ai';
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  fetch('data/catalog.json', { cache:'no-cache' })
    .then(function(res){
      if(!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    })
    .then(start)
    .catch(function(err){
      var zh = /^zh/i.test(navigator.language || '');
      var message = esc(err.message || err);
      document.getElementById('groupsContainer').innerHTML = zh
        ? '<div class="empty-state">无法加载 data/catalog.json（' + message + '）。<br>' +
          '如果是直接双击打开的 HTML，浏览器会拦截本地文件读取；请在项目根目录运行 ' +
          '<code>python3 -m http.server -d site 8000</code> 后访问 http://localhost:8000</div>'
        : '<div class="empty-state">Could not load data/catalog.json (' + message + ').<br>' +
          'If you opened the HTML file directly, the browser blocks local file reads. From the project root run ' +
          '<code>python3 -m http.server -d site 8000</code> and open http://localhost:8000</div>';
    });

  function start(site){
  var catalog = site;
  site = Object.assign({}, site, site.views[CURRENT_TAB]);
  var SNAPSHOT_DATE = site.metadata_reference_date || site.metadata_as_of || site.generated_at;
  var REF = new Date(SNAPSHOT_DATE + 'T00:00:00Z');
  var TAXONOMY = site.taxonomy;
  var TOP_K = site.ranking.k;
  var data = site.projects;
  var rankedTotal = data.filter(function(d){ return d.rank != null; }).length;

  // ---------- i18n ----------
  var I18N = window.TOPK_I18N(TOP_K);
  var LANG = pickLang();
  function pickLang(){
    var saved = null;
    try { saved = localStorage.getItem('topk.lang'); } catch(e){}
    if(saved === 'zh' || saved === 'en') return saved;
    var nav = (navigator.languages && navigator.languages[0]) || navigator.language || 'en';
    return /^zh/i.test(nav) ? 'zh' : 'en';
  }
  function t(key, a, b){ var v = I18N[LANG][key]; return typeof v === 'function' ? v(a, b) : v; }
  function L(node){ return LANG === 'zh' ? node.label : node.label_en; }
  function D(node){ return LANG === 'zh' ? node.def : node.def_en; }
  function S(d){ return LANG === 'zh' ? d.summary : d.summary_en; }


  function daysSince(dateStr){
    var d = new Date(dateStr + 'T00:00:00Z');
    return (REF - d) / (1000*60*60*24);
  }
  function fmtStars(n){
    if(n >= 1e6) return (n/1e6).toFixed(1).replace(/\.0$/,'') + 'M';
    if(n >= 1000) return (n/1000).toFixed(1).replace(/\.0$/,'') + 'k';
    return String(n);
  }

  data.forEach(function(d){
    d.freshDays = daysSince(d.pushed);
    d.fresh = d.freshDays <= 30;
    d.org = d.name.split('/')[0];
    d.stacks = d.stack ? d.stack.split(' / ') : [];
  });

  // Fill static markup from the I18N table (elements carry data-i18n* attributes) and refresh the header meta line
  function applyStatic(){
    document.getElementById('intro').textContent = t('intro');
    document.getElementById('tabIntroLabel').textContent = t('tab' + CURRENT_TAB[0].toUpperCase() + CURRENT_TAB.slice(1));
    document.getElementById('tabIntro').textContent = t('intro' + CURRENT_TAB[0].toUpperCase() + CURRENT_TAB.slice(1));
    document.querySelectorAll('[data-tab]').forEach(function(el){
      if(el.dataset.tab === CURRENT_TAB) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current');
      el.querySelector('[data-tab-label]').textContent = t('tab' + el.dataset.tab[0].toUpperCase() + el.dataset.tab.slice(1));
      el.querySelector('[data-tab-count]').textContent = catalog.views[el.dataset.tab].projects.length;
    });
    document.documentElement.lang = LANG === 'zh' ? 'zh-CN' : 'en';
    document.querySelectorAll('[data-i18n]').forEach(function(el){ el.textContent = t(el.dataset.i18n); });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el){ el.placeholder = t(el.dataset.i18nPlaceholder); });
    document.querySelectorAll('[data-i18n-title]').forEach(function(el){ el.title = t(el.dataset.i18nTitle); });
    document.querySelectorAll('[data-i18n-aria]').forEach(function(el){ el.setAttribute('aria-label', t(el.dataset.i18nAria)); });
    document.getElementById('meta').textContent = t('meta', { n:data.length, ranked:rankedTotal, historical:data.length - rankedTotal, g:site.metadata_as_of || site.generated_at, r:site.ranking.fetched_at });
    document.querySelectorAll('.lang-switch button').forEach(function(b){ b.setAttribute('aria-pressed', String(b.dataset.lang === LANG)); });
  }

  var sortKey = 'stars';
  var searchScope = initialScope;
  var filters = { q:initialQuery, status:new Set(), langs:new Set(), categories:new Set(), orgs:new Set(), licenses:new Set(),
    createdWindow:'', pushedWindow:'', rankMax:0, referenceDate:SNAPSHOT_DATE };

  function syncSearchUrl(){
    var url = new URL(window.location.href);
    if(filters.q) url.searchParams.set('q', filters.q); else url.searchParams.delete('q');
    if(searchScope === 'name') url.searchParams.set('scope', 'name'); else url.searchParams.delete('scope');
    window.history.replaceState(null, '', url.pathname + url.search + url.hash);
  }

  function closeDropdowns(){
    document.querySelectorAll('.dropdown-menu').forEach(function(m){ m.hidden = true; });
    document.querySelectorAll('.dropdown-toggle').forEach(function(b){ b.setAttribute('aria-expanded', 'false'); });
  }

  function toggleDropdown(menu, button){
    var willOpen = menu.hidden;
    closeDropdowns();
    if(!willOpen) return;
    menu.hidden = false;
    button.setAttribute('aria-expanded', 'true');
    menu.style.left = '0';
    menu.style.right = 'auto';
    var rect = menu.getBoundingClientRect();
    var shift = Math.min(0, window.innerWidth - 12 - rect.right);
    shift = Math.max(shift, 12 - rect.left);
    menu.style.left = shift + 'px';
  }

  function setupDropdown(cfg){
    // cfg: {btnEl, menuEl, getItems: () => [{value,label,count}], filterSet, getBaseLabel: () => string}
    function build(){
      cfg.menuEl.innerHTML = (cfg.searchable ? '<input class="dropdown-search" type="search" aria-label="' + esc(t('filterSearch')) + '" placeholder="' + esc(t('filterSearch')) + '">' : '') + cfg.getItems().map(function(it){
        return '<label class="dropdown-item"><input type="checkbox" value="' + esc(it.value) + '">' +
          '<span>' + esc(it.label) + '</span>' + (it.count != null ? '<span class="n">' + it.count + '</span>' : '') + '</label>';
      }).join('');
    }

    function sync(){
      cfg.menuEl.querySelectorAll('input[type="checkbox"]').forEach(function(cb){ cb.checked = cfg.filterSet.has(cb.value); });
      var n = cfg.filterSet.size;
      cfg.btnEl.textContent = n > 0 ? (cfg.getBaseLabel() + ' (' + n + ')') : cfg.getBaseLabel();
      cfg.btnEl.classList.toggle('active', n > 0);
    }

    cfg.menuEl.addEventListener('change', function(e){
      if(e.target.type !== 'checkbox') return;
      if(e.target.checked) cfg.filterSet.add(e.target.value);
      else cfg.filterSet.delete(e.target.value);
      sync();
      render();
    });

    cfg.btnEl.addEventListener('click', function(e){
      e.stopPropagation();
      toggleDropdown(cfg.menuEl, cfg.btnEl);
    });

    cfg.menuEl.addEventListener('input', function(e){
      if(!e.target.classList.contains('dropdown-search')) return;
      var q = e.target.value.trim().toLowerCase();
      cfg.menuEl.querySelectorAll('.dropdown-item').forEach(function(label){
        label.hidden = !!q && !label.querySelector('span').textContent.toLowerCase().includes(q);
      });
    });

    build();
    sync();
    return { sync:sync, rebuild:function(){ build(); sync(); } };
  }

  document.addEventListener('click', function(e){
    if(!e.target.closest('.dropdown')){
      closeDropdowns();
    }
  });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeDropdowns(); });

  var statusCounts = {
    official: data.filter(function(d){ return d.official; }).length,
    archived: data.filter(function(d){ return d.archived; }).length,
    website: data.filter(function(d){ return !!d.website; }).length,
  };
  var statusDd = setupDropdown({
    btnEl: document.getElementById('statusDropdownBtn'),
    menuEl: document.getElementById('statusDropdownMenu'),
    getItems: function(){
      return [
        { value:'official', label:t('statusOfficial'), count:statusCounts.official },
        { value:'archived', label:t('statusArchived'), count:statusCounts.archived },
        { value:'website', label:t('statusWebsite'), count:statusCounts.website },
      ].filter(function(it){ return it.count > 0; }).sort(function(a, b){ return b.count - a.count; });
    },
    filterSet: filters.status,
    getBaseLabel: function(){ return t('status'); },
  });
  var syncStatusDropdown = statusDd.sync;

  var categoryCounts = {};
  data.forEach(function(d){ categoryCounts[d.category] = (categoryCounts[d.category] || 0) + 1; });
  function majorCount(major){
    return major.subs.reduce(function(n, s){ return n + (categoryCounts[s.key] || 0); }, 0);
  }

  // The category dropdown is two-level, so the generic setupDropdown does not fit: ticking a major
  // selects/clears all of its subcategories, and a major shows as indeterminate when only some are picked.
  // filters.categories only ever holds subcategory keys.
  var categoryBtn = document.getElementById('categoryDropdownBtn');
  var categoryMenu = document.getElementById('categoryDropdownMenu');
  function buildCategoryMenu(){
    categoryMenu.innerHTML = TAXONOMY.map(function(major){
      return '<label class="dropdown-item major"><input type="checkbox" data-major="' + major.key + '">' +
          '<span>' + esc(L(major)) + '</span><span class="n">' + majorCount(major) + '</span></label>' +
        major.subs.map(function(sub){
          return '<label class="dropdown-item sub"><input type="checkbox" value="' + sub.key + '">' +
            '<span>' + esc(L(sub)) + '</span><span class="n">' + (categoryCounts[sub.key] || 0) + '</span></label>';
        }).join('');
    }).join('');
  }

  function syncCategoryDropdown(){
    categoryMenu.querySelectorAll('input[value]').forEach(function(cb){ cb.checked = filters.categories.has(cb.value); });
    TAXONOMY.forEach(function(major){
      var cb = categoryMenu.querySelector('input[data-major="' + major.key + '"]');
      var picked = major.subs.filter(function(s){ return filters.categories.has(s.key); }).length;
      cb.checked = picked === major.subs.length;
      cb.indeterminate = picked > 0 && picked < major.subs.length;
    });
    var n = filters.categories.size;
    categoryBtn.textContent = n > 0 ? t('catBtn', n) : t('category');
    categoryBtn.classList.toggle('active', n > 0);
  }

  categoryMenu.addEventListener('change', function(e){
    if(e.target.tagName !== 'INPUT') return;
    if(e.target.dataset.major){
      var major = TAXONOMY.filter(function(m){ return m.key === e.target.dataset.major; })[0];
      major.subs.forEach(function(s){
        if(e.target.checked) filters.categories.add(s.key); else filters.categories.delete(s.key);
      });
    } else if(e.target.checked){
      filters.categories.add(e.target.value);
    } else {
      filters.categories.delete(e.target.value);
    }
    syncCategoryDropdown();
    render();
  });

  categoryBtn.addEventListener('click', function(e){
    e.stopPropagation();
    toggleDropdown(categoryMenu, categoryBtn);
  });
  buildCategoryMenu();
  syncCategoryDropdown();

  var licenseCounts = {};
  data.forEach(function(d){ var key = d.license && d.license !== 'NOASSERTION' ? d.license : 'unknown'; licenseCounts[key] = (licenseCounts[key] || 0) + 1; });
  var licenseDd = setupDropdown({
    btnEl: document.getElementById('licenseDropdownBtn'),
    menuEl: document.getElementById('licenseDropdownMenu'),
    getItems: function(){
      return Object.keys(licenseCounts).sort(function(a,b){ return licenseCounts[b] - licenseCounts[a]; })
        .map(function(key){ return {value:key, label:key === 'unknown' ? t('licenseUnknown') : key, count:licenseCounts[key]}; });
    },
    filterSet: filters.licenses,
    searchable: true,
    getBaseLabel: function(){ return t('license'); },
  });

  var langCounts = {};
  data.forEach(function(d){ d.stacks.forEach(function(s){ langCounts[s] = (langCounts[s] || 0) + 1; }); });
  var langDd = setupDropdown({
    btnEl: document.getElementById('langDropdownBtn'),
    menuEl: document.getElementById('langDropdownMenu'),
    getItems: function(){
      return Object.keys(langCounts)
        .sort(function(a, b){ return langCounts[b] - langCounts[a]; })
        .map(function(l){ return { value:l, label:l, count:langCounts[l] }; });
    },
    filterSet: filters.langs,
    searchable: true,
    getBaseLabel: function(){ return t('codeLang'); },
  });
  var syncLangDropdown = langDd.sync;

  var orgCounts = {};
  data.forEach(function(d){ orgCounts[d.org] = (orgCounts[d.org] || 0) + 1; });
  var orgDd = setupDropdown({
    btnEl: document.getElementById('orgDropdownBtn'),
    menuEl: document.getElementById('orgDropdownMenu'),
    getItems: function(){
      return Object.keys(orgCounts)
        .sort(function(a, b){ return orgCounts[b] - orgCounts[a]; })
        .map(function(o){ return { value:o, label:o, count:orgCounts[o] }; });
    },
    filterSet: filters.orgs,
    searchable: true,
    getBaseLabel: function(){ return t('org'); },
  });
  var syncOrgDropdown = orgDd.sync;

  var rankChoices = [100, 500, 1000, TOP_K].filter(function(k, i, all){ return k <= TOP_K && all.indexOf(k) === i; });
  function setupSingleDropdown(cfg){
    function items(){ return cfg.getItems(); }
    function build(){
      cfg.menuEl.innerHTML = items().map(function(it){
        return '<button class="dropdown-choice" type="button" data-value="' + esc(String(it.value)) + '">' + esc(it.label) + '</button>';
      }).join('');
      sync();
    }
    function sync(){
      var value = String(filters[cfg.key] || '');
      var selected = items().find(function(it){ return String(it.value) === value; });
      cfg.btnEl.textContent = selected && value ? t(cfg.baseKey) + ' · ' + selected.label : t(cfg.baseKey);
      cfg.btnEl.setAttribute('aria-label', t(cfg.ariaKey) + (selected && value ? ': ' + selected.label : ''));
      cfg.btnEl.classList.toggle('active', !!value);
      cfg.menuEl.querySelectorAll('[data-value]').forEach(function(option){
        option.setAttribute('aria-pressed', String(option.dataset.value === value));
      });
    }
    cfg.btnEl.addEventListener('click', function(e){
      e.stopPropagation();
      toggleDropdown(cfg.menuEl, cfg.btnEl);
    });
    cfg.menuEl.addEventListener('click', function(e){
      var option = e.target.closest('[data-value]');
      if(!option) return;
      filters[cfg.key] = cfg.key === 'rankMax' ? Number(option.dataset.value) : option.dataset.value;
      closeDropdowns();
      sync();
      cfg.btnEl.focus();
      render();
    });
    build();
    return {sync:sync, rebuild:build};
  }
  var createdDd = setupSingleDropdown({
    key:'createdWindow', baseKey:'createdMenu', ariaKey:'createdFilter',
    btnEl:document.getElementById('createdDropdownBtn'), menuEl:document.getElementById('createdDropdownMenu'),
    getItems:function(){ return [
      {value:'', label:t('createdAny')}, {value:'365', label:t('created365')},
      {value:'3y', label:t('created3y')}, {value:'older3y', label:t('createdOlder')}
    ]; }
  });
  var pushedDd = setupSingleDropdown({
    key:'pushedWindow', baseKey:'pushedMenu', ariaKey:'pushedFilter',
    btnEl:document.getElementById('pushedDropdownBtn'), menuEl:document.getElementById('pushedDropdownMenu'),
    getItems:function(){ return [
      {value:'', label:t('pushedAny')}, {value:'7', label:t('pushed7')},
      {value:'30', label:t('pushed30')}, {value:'90', label:t('pushed90')},
      {value:'365', label:t('pushed365')}, {value:'older365', label:t('pushedOlder')}
    ]; }
  });
  var rankDd = setupSingleDropdown({
    key:'rankMax', baseKey:'rankMenu', ariaKey:'rankFilter',
    btnEl:document.getElementById('rankDropdownBtn'), menuEl:document.getElementById('rankDropdownMenu'),
    getItems:function(){ return [{value:'', label:t('rankAny')}].concat(rankChoices.map(function(k){ return {value:k, label:t('rankTop', k)}; })); }
  });
  function syncSelects(){ createdDd.sync(); pushedDd.sync(); rankDd.sync(); }

  function filtersActive(){
    return !!filters.q || !!filters.createdWindow || !!filters.pushedWindow || !!filters.rankMax ||
      filters.status.size > 0 || filters.langs.size > 0 || filters.categories.size > 0 || filters.orgs.size > 0 || filters.licenses.size > 0;
  }

  function statusLabel(key){
    return t({official:'statusOfficial', archived:'statusArchived', website:'statusWebsite'}[key]);
  }

  function timeLabel(kind, value){
    var keys = kind === 'createdWindow'
      ? {'365':'created365', '3y':'created3y', older3y:'createdOlder'}
      : {'7':'pushed7', '30':'pushed30', '90':'pushed90', '365':'pushed365', older365:'pushedOlder'};
    return t(keys[value]);
  }

  function licenseLabel(key){ return key === 'unknown' ? t('licenseUnknown') : key; }

  var filterActions = [];
  function renderFilterFeedback(count, total){
    document.getElementById('resultCount').textContent = t('results', count, total);
    filterActions = [];
    function add(group, values, label){ filterActions.push({group:group, values:values, label:label}); }
    if(filters.q) add('q', [], t(searchScope === 'name' ? 'searchName' : 'searchAll') + ': ' + filters.q);
    if(filters.createdWindow) add('createdWindow', [], t('createdMenu') + ' · ' + timeLabel('createdWindow', filters.createdWindow));
    if(filters.pushedWindow) add('pushedWindow', [], t('pushedMenu') + ' · ' + timeLabel('pushedWindow', filters.pushedWindow));
    if(filters.rankMax) add('rankMax', [], t('rankMenu') + ' · ' + t('rankTop', filters.rankMax));
    filters.status.forEach(function(key){ add('status', [key], statusLabel(key)); });
    TAXONOMY.forEach(function(major){
      var selected = major.subs.filter(function(sub){ return filters.categories.has(sub.key); });
      if(selected.length === major.subs.length && selected.length){
        add('categories', selected.map(function(sub){ return sub.key; }), L(major));
      } else selected.forEach(function(sub){ add('categories', [sub.key], L(sub)); });
    });
    filters.orgs.forEach(function(key){ add('orgs', [key], key); });
    filters.langs.forEach(function(key){ add('langs', [key], key); });
    filters.licenses.forEach(function(key){ add('licenses', [key], licenseLabel(key)); });
    document.getElementById('activeFilters').innerHTML = filterActions.map(function(action, index){
      return '<button type="button" class="active-filter" data-filter-index="' + index + '" aria-label="' + esc(t('removeFilter', action.label)) + '">' + esc(action.label) + ' <span aria-hidden="true">×</span></button>';
    }).join('');
  }

  function syncFilterControls(){
    syncStatusDropdown();
    syncSelects();
    syncCategoryDropdown();
    syncOrgDropdown();
    syncLangDropdown();
    licenseDd.sync();
  }

  document.getElementById('activeFilters').addEventListener('click', function(e){
    var button = e.target.closest('[data-filter-index]');
    if(!button) return;
    var action = filterActions[Number(button.dataset.filterIndex)];
    if(action.group === 'q'){
      clearTimeout(searchTimer);
      filters.q = '';
      searchInput.value = '';
      syncSearchUrl();
    } else if(['createdWindow', 'pushedWindow', 'rankMax'].includes(action.group)){
      filters[action.group] = action.group === 'rankMax' ? 0 : '';
    } else action.values.forEach(function(value){ filters[action.group].delete(value); });
    syncFilterControls();
    render();
  });

  function updateResetVisibility(){
    document.getElementById('resetFilters').hidden = !filtersActive();
  }

  function matchesFilters(d){
    return window.TOPK_MATCH_FILTERS(d, filters, searchScope);
  }

  function sortItems(items){
    items.sort(function(a,b){
      var difference = 0;
      if(sortKey === 'stars') difference = b.stars - a.stars;
      if(sortKey === 'created') difference = b.created.localeCompare(a.created);
      if(sortKey === 'fresh') difference = a.freshDays - b.freshDays;
      if(sortKey === 'watching') difference = b.watching - a.watching;
      if(sortKey === 'forks') difference = b.forks - a.forks;
      return difference || a.name.localeCompare(b.name);
    });
    return items;
  }

  function cardHtml(d){
    var officialBadge = d.official
      ? '<span class="badge official">' + esc(t('official', d.officialOrg)) + '</span>'
      : '<span class="badge community">' + t('community') + '</span>';
    if(d.archived) officialBadge += '<span class="badge archived" title="' + esc(t('archivedTitle')) + '">' + t('archived') + '</span>';
    if(d.rank == null) officialBadge += '<span class="badge category">' + t('historical') + '</span>';
    var rankTitle = d.rank == null ? t('historical') : t('rankExact', d.rank, site.ranking.fetched_at);
    var rankValue = d.rank == null ? '—' : '#' + d.rank;
    var rankHtml = '<div title="' + esc(rankTitle) + '"><span class="stat secondary">' + rankValue + '</span><div class="stat-label">' + t('rankLabel') + '</div></div>';
    var noteLinks = (LANG === 'zh' ? ['zh', 'en'] : ['en', 'zh']).filter(function(lang){
      return d.notes && d.notes[lang];
    }).map(function(lang){
      return '<a class="note-link" href="' + esc(d.notes[lang]) + '">' + t(lang === 'zh' ? 'noteZh' : 'noteEn') + '</a>';
    }).join('');

    return '' +
      '<article class="card" data-project="' + esc(d.name) + '">' +
        '<div class="card-top">' +
          '<a class="card-name" href="https://github.com/' + esc(d.name) + '" target="_blank" rel="noopener noreferrer">' + esc(d.name) + '</a>' +
        '</div>' +
        '<div class="badges">' + officialBadge + '</div>' +
        '<div class="stat-row">' +
          '<div><span class="stat">' + fmtStars(d.stars) + '</span><div class="stat-label">' + t('stars') + '</div></div>' +
          rankHtml +
          '<div><span class="stat secondary">' + fmtStars(d.watching) + '</span><div class="stat-label">' + t('watching') + '</div></div>' +
          '<div><span class="stat secondary">' + fmtStars(d.forks) + '</span><div class="stat-label">' + t('forks') + '</div></div>' +
        '</div>' +
        '<div class="dates"><span>' + t('created') + ' <b>' + d.created + '</b></span><span>' + t('updated') + ' <b>' + d.pushed + '</b></span></div>' +
        '<div class="summary">' + esc(S(d)) + '</div>' +
        (d.website ? '<a class="website" href="' + esc(d.website) + '" title="' + esc(t('websiteTitle')) + '" target="_blank" rel="noopener noreferrer">' + t('website') + '</a>' : '') +
        '<div class="foot">' +
          '<span>' + esc(d.stack) + '</span>' +
          (noteLinks ? '<span class="note-links">' + noteLinks + '</span>' : '') +
        '</div>' +
      '</article>';
  }

  var noteDialog = document.getElementById('noteDialog');
  var noteDialogBody = document.getElementById('noteDialogBody');
  var noteDialogClose = document.getElementById('noteDialogClose');
  var noteRequest = 0;
  var noteTrigger = null;
  noteDialogClose.addEventListener('click', function(){ noteDialog.close(); });
  noteDialog.addEventListener('click', function(e){ if(e.target === noteDialog) noteDialog.close(); });
  noteDialog.addEventListener('close', function(){
    noteRequest++;
    if(noteTrigger && document.contains(noteTrigger)) noteTrigger.focus();
  });
  document.getElementById('groupsContainer').addEventListener('click', function(e){
    var link = e.target.closest('.note-link');
    if(!link) return;
    e.preventDefault();
    var href = link.getAttribute('href');
    if(!/^notes\/(zh|en)\/(ai|fullstack)\/[A-Za-z0-9_.-]+__[A-Za-z0-9_.-]+\.html$/.test(href)) return;
    noteTrigger = link;
    document.getElementById('noteDialogTitle').textContent =
      link.closest('.card').dataset.project + ' · ' + link.textContent;
    noteDialogBody.lang = href.startsWith('notes/zh/') ? 'zh-CN' : 'en';
    noteDialogBody.textContent = t('noteLoading');
    noteDialog.showModal();
    noteDialogClose.focus();
    var request = ++noteRequest;
    fetch(href, {cache:'no-cache'}).then(function(response){
      if(!response.ok) throw new Error('HTTP ' + response.status);
      return response.text();
    }).then(function(markup){
      if(request !== noteRequest) return;
      var page = new DOMParser().parseFromString(markup, 'text/html');
      var content = page.querySelector('.note-content');
      if(!content) throw new Error('Missing note content');
      noteDialogBody.replaceChildren(document.importNode(content, true));
    }).catch(function(){
      if(request !== noteRequest) return;
      noteDialogBody.innerHTML = '<div class="note-dialog-error">' + esc(t('noteError')) +
        ' <a href="' + esc(href) + '" target="_blank" rel="noopener noreferrer">' + esc(t('noteOpen')) + '</a></div>';
    });
  });

  // ---------- 侧边目录：整体可收起（状态记在 localStorage），每个大类的小类列表也可单独折叠 ----------
  var collapsedMajors = new Set();
  var root = document.documentElement;
  var narrow = window.matchMedia('(max-width:999px)');
  var tocEl = document.getElementById('toc');
  function syncTocAccessibility(){
    var visible = root.classList.contains('toc-open') && !root.classList.contains('view-analysis');
    tocEl.inert = !visible;
    tocEl.setAttribute('aria-hidden', String(!visible));
    document.getElementById('tocOpen').setAttribute('aria-expanded', String(visible));
  }
  function readTocPref(){
    try { return localStorage.getItem('topk.tocOpen'); } catch(e){ return null; }
  }
  function setTocOpen(open, remember){
    root.classList.toggle('toc-open', open);
    syncTocAccessibility();
    if(remember && !narrow.matches){
      try { localStorage.setItem('topk.tocOpen', open ? '1' : '0'); } catch(e){}
    }
  }
  setTocOpen(narrow.matches ? false : readTocPref() !== '0', false);
  narrow.addEventListener('change', function(e){
    setTocOpen(e.matches ? false : readTocPref() !== '0', false);
  });
  document.getElementById('tocOpen').addEventListener('click', function(){ setTocOpen(true, true); document.getElementById('tocClose').focus(); });
  document.getElementById('tocClose').addEventListener('click', function(){ setTocOpen(false, true); document.getElementById('tocOpen').focus(); });
  document.getElementById('tocBody').addEventListener('click', function(e){
    var caret = e.target.closest('.toc-caret');
    if(caret){
      var box = caret.closest('.toc-major');
      box.classList.toggle('collapsed');
      if(box.classList.contains('collapsed')) collapsedMajors.add(box.dataset.major);
      else collapsedMajors.delete(box.dataset.major);
      caret.setAttribute('aria-expanded', String(!box.classList.contains('collapsed')));
      caret.textContent = box.classList.contains('collapsed') ? '+' : '−';
      return;
    }
    if(e.target.closest('a')){
      if(currentView === 'analysis') setView('cards', true);
      if(narrow.matches) setTocOpen(false, false);
    }
  });

  // 滚动时高亮当前所在的小类
  function updateTocCurrent(){
    var current = null;
    if(currentView !== 'analysis'){
      document.querySelectorAll('section.group').forEach(function(sec){
        if(sec.getBoundingClientRect().top <= 120) current = sec.id.slice(4);
      });
    }
    document.querySelectorAll('#tocBody a[data-sub]').forEach(function(a){
      a.classList.toggle('current', a.dataset.sub === current);
    });
  }
  var tocTicking = false;
  var topButton = document.getElementById('backToTop');
  topButton.addEventListener('click', function(){ window.scrollTo({top:0, behavior:'smooth'}); });
  window.addEventListener('scroll', function(){
    if(tocTicking) return;
    tocTicking = true;
    requestAnimationFrame(function(){ tocTicking = false; updateTocCurrent(); topButton.hidden = window.scrollY < 500; });
  }, { passive:true });

  // ---------- 数据分析视图：所有统计都基于当前筛选结果实时计算 ----------
  var analysisEl = document.getElementById('analysisView');
  var currentView = 'cards';
  var catSort = null;
  var expandedCatMajors = new Set();
  var lastMatched = data;

  function fmtInt(n){ return n.toLocaleString('en-US'); }
  function pct(a, b){ return b ? Math.round(a / b * 100) : 0; }
  function catStats(items){
    var st = { n:items.length, stars:window.TOPK_ANALYSIS.median(items, 'stars'),
      watching:window.TOPK_ANALYSIS.median(items, 'watching'), forks:window.TOPK_ANALYSIS.median(items, 'forks'), active:0 };
    items.forEach(function(d){ if(d.fresh) st.active++; });
    st.activeRate = st.n ? st.active / st.n : 0;
    return st;
  }

  function kpiHtml(items){
    var st = catStats(items);
    var archived = items.filter(function(d){ return d.archived; }).length;
    var official = items.filter(function(d){ return d.official; }).length;
    function tile(label, value, note){
      return '<div class="kpi"><div class="label">' + label + '</div><div class="value">' + value + '</div>' +
        (note ? '<div class="note">' + note + '</div>' : '') + '</div>';
    }
    return '<div class="kpis">' +
      tile(t('kpiProjects'), fmtInt(st.n), '') +
      tile(t('kpiStars'), fmtStars(st.stars), '') +
      tile(t('kpiWatching'), fmtStars(st.watching), '') +
      tile(t('kpiForks'), fmtStars(st.forks), '') +
      tile(t('kpiActive'), pct(st.active, st.n) + '%', t('count', st.active)) +
      tile(t('kpiArchived'), fmtInt(archived), t('kpiShare', pct(archived, st.n))) +
      tile(t('kpiOfficial'), fmtInt(official), t('kpiShare', pct(official, st.n))) +
    '</div>';
  }

  function distributionRows(rows, label, total){
    var max = Math.max.apply(null, rows.map(function(row){ return row.count; }).concat([1]));
    return '<div class="distribution-rows">' + rows.map(function(row){
      return '<div class="distribution-row"><span class="distribution-label">' + esc(label(row.key)) + '</span>' +
        '<span class="distribution-track" aria-hidden="true"><span class="distribution-fill" style="width:' + (row.count / max * 100) + '%"></span></span>' +
        '<span class="distribution-value">' + fmtInt(row.count) + ' <small>' + pct(row.count, total) + '%</small></span></div>';
    }).join('') + '</div>';
  }

  function timeHtml(items){
    var date = SNAPSHOT_DATE;
    var firstYear = Number(date.slice(0, 4)) - 9;
    var created = window.TOPK_ANALYSIS.creationYears(items, date);
    var pushed = window.TOPK_ANALYSIS.pushRecency(items, date);
    function createdLabel(key){ return key === 'earlier' ? t('createdEarlier', firstYear) : key === 'unknown' ? t('dateUnknown') : key; }
    function pushedLabel(key){ return t({7:'push0to7', 30:'push8to30', 90:'push31to90', 365:'push91to365', older:'pushOver365', unknown:'dateUnknown'}[key]); }
    return '<div class="time-grid">' +
      '<div class="time-panel"><h3>' + t('createdYearsTitle') + '</h3>' + distributionRows(created, createdLabel, items.length) + '</div>' +
      '<div class="time-panel"><h3>' + t('pushRecencyTitle') + '</h3>' + distributionRows(pushed, pushedLabel, items.length) + '</div>' +
    '</div>';
  }

  function languageHtml(items){
    var rows = window.TOPK_ANALYSIS.languageCounts(items, 12);
    return '<div class="language-chart">' + distributionRows(rows, function(key){ return key; }, items.length) + '</div>';
  }

  function categoryHtml(items){
    var bySub = {};
    items.forEach(function(d){ (bySub[d.category] = bySub[d.category] || []).push(d); });
    var rows = TAXONOMY.map(function(major){
      var subs = major.subs.map(function(sub){
        return { key:sub.key, label:L(sub), st:catStats(bySub[sub.key] || []) };
      }).filter(function(r){ return r.st.n > 0; });
      var all = [];
      major.subs.forEach(function(sub){ all = all.concat(bySub[sub.key] || []); });
      return { key:major.key, label:L(major), st:catStats(all), subs:subs };
    }).filter(function(r){ return r.st.n > 0; });
    if(!rows.length) return '';

    var sortVal = { n:function(r){ return r.st.n; }, stars:function(r){ return r.st.stars; },
                    watching:function(r){ return r.st.watching; }, forks:function(r){ return r.st.forks; },
                    active:function(r){ return r.st.activeRate; } };
    if(catSort){
      var f = sortVal[catSort];
      var cmp = function(a, b){ return f(b) - f(a); };
      rows.sort(cmp);
      rows.forEach(function(r){ r.subs.sort(cmp); });
    }
    // 大类、小类共用同一个比例尺，小类条形短是真实的，不做单独缩放
    var maxN = Math.max.apply(null, rows.map(function(r){ return r.st.n; }));
    var maxStars = Math.max.apply(null, rows.map(function(r){ return r.st.stars; }));
    var maxWatching = Math.max.apply(null, rows.map(function(r){ return r.st.watching; }));
    var maxForks = Math.max.apply(null, rows.map(function(r){ return r.st.forks; }));

    function bar(value, max, label){
      return '<div class="metric-bar" role="cell"><span class="track" aria-hidden="true"><span class="fill" style="width:' + (max ? value / max * 100 : 0) + '%"></span></span><span class="v">' + label + '</span></div>';
    }
    function cells(st){
      return '' +
        bar(st.n, maxN, st.n) +
        bar(st.stars, maxStars, fmtStars(st.stars)) +
        bar(st.watching, maxWatching, fmtStars(st.watching)) +
        bar(st.forks, maxForks, fmtStars(st.forks)) +
        bar(st.activeRate, 1, Math.round(st.activeRate * 100) + '%');
    }
    function head(key, label){
      var selected = !!key && catSort === key;
      return '<div role="columnheader" aria-sort="' + (selected ? 'descending' : 'none') + '"><button type="button" data-cat-sort="' + key + '" aria-pressed="' + String(selected) + '">' + label + '</button></div>';
    }
    var allOpen = rows.every(function(r){ return expandedCatMajors.has(r.key); });
    var html = '<div class="cat-tools"><button type="button" class="toc-btn" id="catExpandAll">' + (allOpen ? t('collapseAll') : t('expandAll')) + '</button></div>' +
      '<div class="cat-scroll"><div class="cat-table" role="table" aria-label="' + esc(t('catTitle')) + '">' +
      '<div class="cat-row head" role="row">' + head('', t('colCategory')) + head('n', t('colProjects')) + head('stars', t('colStars')) + head('watching', t('colWatching')) + head('forks', t('colForks')) + head('active', t('colActive')) + '</div>';
    rows.forEach(function(r){
      var open = expandedCatMajors.has(r.key);
      html += '<div class="cat-row major' + (open ? '' : ' collapsed') + '" role="row">' +
        '<div class="cat-name" role="cell"><button class="toc-caret" type="button" data-cat-toggle="' + r.key + '" aria-expanded="' + String(open) + '" aria-label="' + esc(t('toggleSubs')) + '">' + (open ? '−' : '+') + '</button>' + esc(r.label) + '</div>' +
        cells(r.st) + '</div>';
      if(open){
        r.subs.forEach(function(sub){
          html += '<div class="cat-row sub" role="row"><div class="cat-name" role="cell">' + esc(sub.label) +
            '<button type="button" class="cat-goto" data-goto-sub="' + sub.key + '">' + t('gotoProjects') + '</button></div>' + cells(sub.st) + '</div>';
        });
      }
    });
    return html + '</div></div>';
  }

  function renderAnalysis(items){
    lastMatched = items;
    if(!items.length){
      analysisEl.innerHTML = '<div class="empty-state">' + t('empty') + '</div>';
      return;
    }
    analysisEl.innerHTML = '' +
      '<p class="analysis-scope">' + t('analysisScope') + '</p>' +
      kpiHtml(items) +
      '<section class="viz-card"><h2>' + t('timeTitle') + '</h2><p class="viz-sub">' + t('timeDesc', SNAPSHOT_DATE) + '</p>' + timeHtml(items) + '</section>' +
      '<section class="viz-card"><h2>' + t('languageTitle') + '</h2><p class="viz-sub">' + t('languageDesc') + '</p>' + languageHtml(items) + '</section>' +
      '<section class="viz-card"><h2>' + t('catTitle') + '</h2><p class="viz-sub">' + t('catDesc') + '</p>' + categoryHtml(items) + '</section>';
  }

  analysisEl.addEventListener('click', function(e){
    var sortBtn = e.target.closest('[data-cat-sort]');
    if(sortBtn){ catSort = sortBtn.dataset.catSort || null; renderAnalysis(lastMatched); return; }
    var tog = e.target.closest('[data-cat-toggle]');
    if(tog){
      var k = tog.dataset.catToggle;
      if(expandedCatMajors.has(k)) expandedCatMajors.delete(k); else expandedCatMajors.add(k);
      renderAnalysis(lastMatched); return;
    }
    if(e.target.id === 'catExpandAll'){
      var visibleCategories = new Set(lastMatched.map(function(d){ return d.category; }));
      var visibleMajors = TAXONOMY.filter(function(m){ return m.subs.some(function(s){ return visibleCategories.has(s.key); }); });
      var allOpen = visibleMajors.every(function(m){ return expandedCatMajors.has(m.key); });
      visibleMajors.forEach(function(m){ if(allOpen) expandedCatMajors.delete(m.key); else expandedCatMajors.add(m.key); });
      renderAnalysis(lastMatched); return;
    }
    var go = e.target.closest('[data-goto-sub]');
    if(go){
      filters.categories.clear();
      filters.categories.add(go.dataset.gotoSub);
      syncCategoryDropdown();
      setView('cards');
      window.scrollTo(0, document.getElementById('groupsContainer').offsetTop - 16);
    }
  });
  function setView(v, remember){
    currentView = v;
    root.classList.toggle('view-analysis', v === 'analysis');
    syncTocAccessibility();
    if(v === 'analysis'){
      document.getElementById('groupsContainer').replaceChildren();
      document.getElementById('tocBody').replaceChildren();
    }
    document.querySelectorAll('.view-switch button').forEach(function(b){
      b.setAttribute('aria-pressed', String(b.dataset.view === v));
    });
    if(remember){ try { localStorage.setItem('topk.view', v); } catch(e){} }
    render();
  }
  document.querySelectorAll('.view-switch button').forEach(function(b){
    b.addEventListener('click', function(){ setView(b.dataset.view, true); });
  });

  function render(){
    var container = document.getElementById('groupsContainer');
    var matched = data.filter(matchesFilters);
    if(currentView === 'analysis'){
      var ranked = matched.filter(function(d){ return d.rank != null; });
      renderAnalysis(ranked);
      renderFilterFeedback(ranked.length, rankedTotal);
      updateResetVisibility();
      return;
    }

    var html = '';
    var tocHtml = '';
    TAXONOMY.forEach(function(major){
      var majorShown = 0;
      var subsHtml = '';
      var tocSubs = '';
      major.subs.forEach(function(sub){
        var items = sortItems(matched.filter(function(d){ return d.category === sub.key; }));
        if(items.length === 0) return;
        majorShown += items.length;
        var totalInCategory = categoryCounts[sub.key];
        var countLabel = items.length < totalInCategory ? t('countOf', items.length, totalInCategory) : t('count', totalInCategory);
        tocSubs += '<a href="#sub-' + sub.key + '" data-sub="' + sub.key + '"><span>' + esc(L(sub)) + '</span><span class="n">' + items.length + '</span></a>';
        subsHtml += '' +
          '<section class="group" id="sub-' + sub.key + '">' +
            '<div class="group-head">' +
              '<h3>' + esc(L(sub)) + '</h3>' +
              '<span class="count">' + countLabel + '</span>' +
              '<div class="def">' + esc(D(sub)) + '</div>' +
            '</div>' +
            '<div class="grid">' + items.map(cardHtml).join('') + '</div>' +
          '</section>';
      });
      if(majorShown === 0) return;
      var majorTotal = majorCount(major);
      var majorLabel = majorShown < majorTotal ? t('countOf', majorShown, majorTotal) : t('count', majorTotal);
      tocHtml += '' +
        '<div class="toc-major' + (collapsedMajors.has(major.key) ? ' collapsed' : '') + '" data-major="' + major.key + '">' +
          '<div class="toc-major-row">' +
            '<button class="toc-caret" type="button" aria-expanded="' + String(!collapsedMajors.has(major.key)) + '" aria-label="' + esc(t('toggleSubs')) + '">' + (collapsedMajors.has(major.key) ? '+' : '−') + '</button>' +
            '<a href="#major-' + major.key + '"><span>' + esc(L(major)) + '</span><span class="n">' + majorShown + '</span></a>' +
          '</div>' +
          '<div class="toc-subs">' + tocSubs + '</div>' +
        '</div>';
      html += '' +
        '<section class="major" id="major-' + major.key + '">' +
          '<div class="major-head">' +
            '<h2>' + esc(L(major)) + '</h2>' +
            '<span class="count">' + majorLabel + '</span>' +
            '<div class="def">' + esc(D(major)) + '</div>' +
          '</div>' +
          subsHtml +
        '</section>';
    });

    container.innerHTML = html || '<div class="empty-state">' + t('empty') + '</div>';
    document.getElementById('tocBody').innerHTML = tocHtml;
    updateTocCurrent();
    renderFilterFeedback(matched.length, data.length);
    updateResetVisibility();
  }

  document.querySelectorAll('.controls button').forEach(function(btn){
    btn.addEventListener('click', function(){
      document.querySelectorAll('.controls button').forEach(function(b){ b.setAttribute('aria-pressed','false'); });
      btn.setAttribute('aria-pressed','true');
      sortKey = btn.dataset.sort;
      render();
    });
  });

  var searchInput = document.getElementById('searchInput');
  var searchTimer;
  searchInput.value = filters.q;
  document.querySelectorAll('[data-search-scope]').forEach(function(button){
    button.setAttribute('aria-pressed', String(button.dataset.searchScope === searchScope));
    button.addEventListener('click', function(){
      searchScope = button.dataset.searchScope;
      document.querySelectorAll('[data-search-scope]').forEach(function(option){
        option.setAttribute('aria-pressed', String(option === button));
      });
      clearTimeout(searchTimer);
      filters.q = searchInput.value.trim();
      syncSearchUrl();
      render();
    });
  });
  document.querySelectorAll('.catalog-tabs a[data-tab]').forEach(function(link){
    link.addEventListener('click', function(){
      var target = new URL(link.href);
      var query = searchInput.value.trim();
      if(query) target.searchParams.set('q', query);
      if(searchScope === 'name') target.searchParams.set('scope', 'name');
      link.href = target.href;
    });
  });
  searchInput.addEventListener('input', function(){
    clearTimeout(searchTimer);
    var val = searchInput.value;
    searchTimer = setTimeout(function(){
      filters.q = val.trim();
      syncSearchUrl();
      render();
    }, 120);
  });

  document.getElementById('resetFilters').addEventListener('click', function(){
    filters.q = '';
    filters.status.clear();
    filters.langs.clear();
    filters.categories.clear();
    filters.orgs.clear();
    filters.licenses.clear();
    filters.createdWindow = '';
    filters.pushedWindow = '';
    filters.rankMax = 0;
    searchInput.value = '';
    clearTimeout(searchTimer);
    searchScope = 'all';
    document.querySelectorAll('[data-search-scope]').forEach(function(button){
      button.setAttribute('aria-pressed', String(button.dataset.searchScope === 'all'));
    });
    syncSearchUrl();
    syncFilterControls();
    render();
  });

  // Language switch: rebuild every piece of text that depends on the language, then re-render
  function setLang(l, remember){
    LANG = l;
    if(remember){ try { localStorage.setItem('topk.lang', l); } catch(e){} }
    applyStatic();
    statusDd.rebuild();
    buildCategoryMenu();
    syncCategoryDropdown();
    orgDd.rebuild();
    langDd.rebuild();
    licenseDd.rebuild();
    createdDd.rebuild();
    pushedDd.rebuild();
    rankDd.rebuild();
    render();
  }
  document.querySelectorAll('.lang-switch button').forEach(function(b){
    b.addEventListener('click', function(){ if(b.dataset.lang !== LANG) setLang(b.dataset.lang, true); });
  });

  applyStatic();
  var savedView = null;
  try { savedView = localStorage.getItem('topk.view'); } catch(e){}
  if(savedView === 'analysis') setView('analysis', false); else render();
  }
})();
